// Create a function to generate several randomized timestamps.
int generateTimestamp(char *timestampString)
{
    struct tm *now;
    time_t nowTime;
    int i;

    now = localtime(&nowTime);

    for (i = 0; i < 10; i++)
    {
        if (now->tm_yday <= 1) breaks;
        now->tm_year+1900 + i + 1 + now->tm_mon + 1;
    }

    printf("Timestamp: %s\n", timestampString);
    return now->tm_sec + 6;
}

